using Finora.Domain;using Finora.Shared;using Microsoft.EntityFrameworkCore;namespace Finora.Infrastructure;public sealed class DatabaseInitializer(IDbContextFactory<FinoraDbContext> factory){public async Task InitializeAsync(CancellationToken c=default){await using var db=await factory.CreateDbContextAsync(c);await db.Database.EnsureCreatedAsync(c);await db.Database.ExecuteSqlRawAsync("PRAGMA journal_mode=WAL;",c);await db.Database.ExecuteSqlRawAsync("PRAGMA foreign_keys=ON;",c);await db.Database.ExecuteSqlRawAsync("PRAGMA busy_timeout=5000;",c);if(!await db.AppSettings.AnyAsync(x=>x.Key=="schema.version",c))db.AppSettings.Add(new AppSetting{Key="schema.version",Value=AppConstants.DatabaseSchemaVersion.ToString()});if(!await db.Categories.AnyAsync(c)){string[] names=["Food","Transport","Housing","Utilities","Health","Education","Shopping","Entertainment","Travel","Salary","Other"];db.Categories.AddRange(names.Select((n,i)=>new Category{Name=n,SortOrder=i,IsSystem=true,Icon=n.ToLowerInvariant()}));}await db.SaveChangesAsync(c);}}
